-- DROP TABLE public.jcm_schedule;

CREATE TABLE public.jcm_schedule (
	f_id varchar(100) NOT NULL,
	f_name varchar(255) NULL,
	f_alias varchar(255) NULL,
	f_desc varchar(255) NULL,
	f_starttime timestamp NULL,
	f_lltime timestamp NULL,
	f_ultime timestamp NULL,
	f_calendarid varchar(255) NULL,
	f_frequencyid varchar(255) NULL,
	f_messageid varchar(255) NULL,
	f_effective varchar(255) NULL,
	f_dateformatid varchar(255) NULL,
	f_syscode varchar(255) NULL,
	f_createtime timestamp NULL,
	f_updatetime timestamp NULL,
	f_dickey varchar(1200) NULL,
	CONSTRAINT jcm_schedule_pkey PRIMARY KEY (f_id)
);

